type IntegrationScenarioSubject = {
  sourceType?: string
  sourceId?: string
  sourceTitle?: string
  candidatePaths: string[]
  sourceEvidence?: string[]
  expectedContributionClasses?: string[]
  validationProfileIds?: string[]
}

const integrationScenarioIdPattern = /(TC-[A-Z0-9]+(?:-[A-Z0-9]+)*-\d+[A-Z0-9]*)/i
const integrationScenarioSignalPrefix = 'TESTSIG-integration-scenario-'

export function extractIntegrationScenarioIds(subject: IntegrationScenarioSubject): string[] {
  const discoveredIds = new Set<string>()
  const values = [
    subject.sourceTitle ?? '',
    subject.sourceId ?? '',
    ...(subject.sourceEvidence ?? []),
    ...subject.candidatePaths,
  ]

  for (const value of values) {
    const match = value.match(integrationScenarioIdPattern)
    if (!match?.[1]) {
      continue
    }
    discoveredIds.add(match[1].toUpperCase())
  }

  return [...discoveredIds].sort((left, right) => left.localeCompare(right))
}

export function isQaScenarioPath(candidatePath: string): boolean {
  return candidatePath.startsWith('.ai/qa/scenarios/')
    && candidatePath.endsWith('.md')
}

export function isIntegrationScenarioGapTask(subject: IntegrationScenarioSubject): boolean {
  return Boolean(
    (subject.sourceType === 'repo_signal' && subject.sourceId?.startsWith(integrationScenarioSignalPrefix))
    || (extractIntegrationScenarioIds(subject).length > 0 && subject.candidatePaths.some((candidatePath) => isQaScenarioPath(candidatePath))),
  )
}

export function isIntegrationTestTask(subject: IntegrationScenarioSubject): boolean {
  return isIntegrationScenarioGapTask(subject)
    || Boolean(subject.expectedContributionClasses?.includes('tests'))
    || Boolean(subject.validationProfileIds?.includes('integration-tests'))
    || Boolean(subject.validationProfileIds?.includes('integration-test-gap-coverage'))
}
